css:
body, #content, .banner, .horizontal-section, .project-tabs, .project-tabs__panel, .project-description, .site-header, #sticky-notifications, aside, [class*="sidebar"] { background-color: #0d1117 !important; }
body, #content, .project-tabs, .project-description *:not(a), .site-header *:not(a), aside *:not(a), [class*="sidebar"] *:not(a) { color: #e6edf3 !important; }
#content a, .site-header a, aside a, [class*="sidebar"] a { color: #58a6ff !important; }
#content h1, #content h2, #content h3, .project-description h2 { border-color: #30363d !important; }
pre, code { background-color: #161b22 !important; color: #e6edf3 !important; border-color: #30363d !important; }
#search, input, textarea, select { background-color: #161b22 !important; color: #e6edf3 !important; border-color: #30363d !important; }
button { background-color: #21262d !important; color: #e6edf3 !important; border-color: #30363d !important; }
